#include "chimera/vfs.h"
#include <cassert>
#include <cstring>
int main(){assert(chimera_vfs_init()==0);assert(chimera_vfs_mkdir("/tmp")==0);assert(chimera_vfs_create("/tmp/a")==0);const char d[]="filesystem";assert(chimera_vfs_write("/tmp/a",0,d,sizeof(d))==(long long)sizeof(d));char out[32]={};assert(chimera_vfs_read("/tmp/a",0,out,sizeof(out))==(long long)sizeof(d));assert(std::memcmp(out,d,sizeof(d))==0);assert(chimera_vfs_read("/tmp/a",4,out,3)==3&&std::memcmp(out,"sys",3)==0);assert(chimera_vfs_write("/tmp/a",20,"x",1)==1);std::memset(out,0,sizeof(out));assert(chimera_vfs_read("/tmp/a",sizeof(d),out,13)==10);assert(out[0]==0&&out[9]=='x');assert(chimera_vfs_truncate("/tmp/a",4)==0);chimera_vfs_stat st{};assert(chimera_vfs_stat_path("/tmp/a",&st)==0&&st.size==4);assert(chimera_vfs_create("/tmp/../escape")==-22);assert(chimera_vfs_create("/missing/file")==-1);assert(chimera_vfs_unlink("/tmp")==-39);assert(chimera_vfs_rename("/tmp/a","/tmp/b")==0);assert(chimera_vfs_stat_path("/tmp/a",&st)==-2);assert(chimera_vfs_unlink("/tmp/b")==0);assert(chimera_vfs_unlink("/tmp")==0);assert(chimera_vfs_node_count()==0);return 0;}
